sql.where:
 	T1.FINPROD_TYPE2 = #{assestType}
 	AND T1.TRADE_MARKET in(#{TRADE_PLACE_01},#{TRADE_PLACE_05},#{TRADE_PLACE_09},#{TRADE_PLACE_10})

	and T1.FINPROD_MARKET_ID = #{initValue}


	and T1.TRADE_MARKET = #{tradeMarket}


	and (T1.FINPROD_MARKET_ID like '%' || #{search} || '%'
	or T1.FINPROD_NAME like '%' || #{search} || '%'
	or T1.FINPROD_ABBR like '%' || #{search} || '%'

mapper.select:
SELECT '' workflowId, T1.ENTRUST_ID entrustId, T1.PORTFOLIO_ID portfolioId, T1.VDATE vdate, T1.MDATE mdate, T6.ASSET_TYPE1 assetType1,
T6.ASSET_TYPE_10 assetType10, T6.ASSET_TYPE_11 assetType11,
T1.CCY ccy, T1.FINPROD_ID finprodId, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_NAME finprodName, T1.PS ps, T1.TRADE_MARKET tradeMarket, T1.TRADE_PLAT tradePlat, T1.TRADE_MARKET_MODE tradeMarketMode, T1.INV_AIM invAim, T1.AVAILABLE_NUM availableNum, T1.ENTRUST_NUM*100 entrustNum, T6.MIN_AMT minAmt, T1.PRICE price, T1.PRICE_MODEL priceModel, T6.EXER_YIELD*100 exerYield, T6.MATURE_YIELD*100 matureYield, T6.SETTLE_SPREED settleSpeed, T6.SEC_ACCT_ID secAcctId, T6.OUR_ENT_NUM*100 entrustOwnNum, T6.LENDIN_ENT_NUM*100 entrustIntegrateNum, T1.PRO_AVAILABLE_CASH proAvailableCash, T1.ACC_AVAILABLE_CASH accAvailableCash, T1.REMARK remark, T1.COUNTER_ID counterId, T1.COUNTER_TRADER counterTrader, T1.CONTACT_INFO contactInfo, T2.TRADER trader, T1.INV_MANAGER_ID invManagerId, T1.chl_id chlId ,T6.FULL_PRICE fpriceAmt FROM ETR_ENTRUST T1 LEFT JOIN ETR_DISTRIBUTE T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 =#{bond} LEFT JOIN ETR_ENTRUST_ADD T6 ON T1.ENTRUST_ID = T6.ENTRUST_ID
T1.PORTFOLIO_ID=#{portfolioId}
AND T1.FINPROD_ID = #{finprodId}
AND T1.ENTRUST_ID = #{entrustId}
union all SELECT T1.WORKFLOW_ID workflowId, T1.ENTRUST_ID entrustId, T1.PORTFOLIO_ID portfolioId, T1.VDATE vdate, T1.MDATE mdate, T6.ASSET_TYPE1 assetType1,
T6.ASSET_TYPE_10 assetType10, T6.ASSET_TYPE_11 assetType11,
T1.CCY ccy, T1.FINPROD_ID finprodId, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_NAME finprodName, T1.PS ps, T1.TRADE_MARKET tradeMarket, T1.TRADE_PLAT tradePlat, T1.TRADE_MARKET_MODE tradeMarketMode, T1.INV_AIM invAim, T1.AVAILABLE_NUM availableNum, T1.ENTRUST_NUM*100 entrustNum, T6.MIN_AMT minAmt, T1.PRICE price, T1.PRICE_MODEL priceModel, T6.EXER_YIELD*100 exerYield, T6.MATURE_YIELD*100 matureYield, T6.SETTLE_SPREED settleSpeed, T6.SEC_ACCT_ID secAcctId, T6.OUR_ENT_NUM*100 entrustOwnNum, T6.LENDIN_ENT_NUM*100 entrustIntegrateNum, T1.PRO_AVAILABLE_CASH proAvailableCash, T1.ACC_AVAILABLE_CASH accAvailableCash, T1.REMARK remark, T1.COUNTER_ID counterId, T1.COUNTER_TRADER counterTrader, T1.CONTACT_INFO contactInfo, T2.TRADER trader, T1.INV_MANAGER_ID invManagerId, T1.chl_id chlId ,T6.FULL_PRICE fpriceAmt FROM WFL_ETR_ENTRUST T1 LEFT JOIN ETR_DISTRIBUTE T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 =#{bond} LEFT JOIN WFL_ETR_ENTRUST_ADD T6 ON T1.ENTRUST_ID = T6.ENTRUST_ID
T1.PORTFOLIO_ID=#{portfolioId}
AND T1.FINPROD_ID = #{finprodId}
AND T1.ENTRUST_ID = #{entrustId}
